import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"启动故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/boot-failures.md","filePath":"zh/troubleshooting/boot-failures.md"}'),l={name:"zh/troubleshooting/boot-failures.md"};function i(s,o,c,n,d,h){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="启动故障排查" tabindex="-1">启动故障排查 <a class="header-anchor" href="#启动故障排查" aria-label="Permalink to &quot;启动故障排查&quot;">​</a></h1><h2 id="启动日志就是检查清单" tabindex="-1">启动日志就是检查清单 <a class="header-anchor" href="#启动日志就是检查清单" aria-label="Permalink to &quot;启动日志就是检查清单&quot;">​</a></h2><p>内核<strong>按上线顺序</strong>每个子系统打印一行（该顺序即 <a href="./../arch/boot-flow.html">arch/boot-flow.md</a>）。诊断：</p><ol><li><strong>串口上什么都没有</strong>——OCBL 没有运行，或 ISO 条目不对。 启动 ISO 的另一个槽位条目；BIOS 与 UEFI 都试试。</li><li><strong>停在 <code>long mode entry OK</code> 之前</strong>——boot.S 阶段： multiboot2 握手失败（魔数/mbi 不对）——用 <code>-serial file:</code> 捕获并检查 mbi 标签解析。</li><li><strong>停在某个驱动行</strong>——该家族的探测在你的硬件上失败；其 上一条消息点名了设备。移除该设备（或 QEMU 参数）以 确认。</li><li><strong>到达 <code>boot complete</code> 却没有提示符</strong>——shell 初始化 问题；极为罕见（程序注册表计数行会是线索）。</li><li><strong>提示符之后重启</strong>——panic 或看门狗：第二次启动后检查 /etc 的 crashlog（<code>dumpinfo</code>、<code>crashlog</code>），以及事件 发生期间的串口转储。</li></ol><h2 id="自检是你的朋友" tabindex="-1">自检是你的朋友 <a class="header-anchor" href="#自检是你的朋友" aria-label="Permalink to &quot;自检是你的朋友&quot;">​</a></h2><p>启动序列已经证明：异常路径 (3/3)、shell 注册 (284)、崩溃恢复 已布防。如果这些行都打印了，底下的机器是健全的——去看具体 特性，而不是平台。</p><h2 id="第二次启动分析" tabindex="-1">第二次启动分析 <a class="header-anchor" href="#第二次启动分析" aria-label="Permalink to &quot;第二次启动分析&quot;">​</a></h2><p>A/B 标志 + crashlog 在 /etc 上跨重启存活。任何意外复位之后： <code>dmesg</code>（当前启动）、<code>crashlog</code>/<code>dumpinfo</code>（上一次启动）、 <code>abcfg</code>（启动菜单当时试图启动什么）。</p>',8)])])}const m=e(l,[["render",i]]);export{g as __pageData,m as default};
